/* Written by tools/build_film.mjs from narration/film.json: do not edit. Times are seconds. */
export const FILM = {"audio":"assets/audio/film.mp3","voice":"fr_FR-siwis-medium","length":474.75,"steps":[{"id":"aube","from":0,"arrive":0,"voice":1.2,"leave":11.99,"lines":[{"at":1.2,"end":4.28,"text":"Portivechju. Lettre à ceux qui reviennent.","quiet":true},{"at":5.18,"end":10.79,"text":"À vous qui portez ce pays dans un nom, dans une maison, ou seulement dans une façon de dire : là-bas.","quiet":true}],"cues":{},"pins":{}},{"id":"maquette","from":11.99,"arrive":18.99,"voice":14.49,"leave":27.22,"lines":[{"at":14.49,"end":19.53,"text":"Voici la même ville, du même endroit, sous le même angle : en plâtre."},{"at":19.98,"end":22.91,"text":"Pour dire comment elle est venue là, il faut d’abord l’ôter."},{"at":23.36,"end":26.52,"text":"Chì và è volta, bon viaghju face.","sub":"Celui qui part et revient a fait un bon voyage.","kind":"proverb"}],"cues":{},"pins":{}},{"id":"rocher","from":27.22,"arrive":35.22,"voice":30.02,"leave":48.74,"lines":[{"at":30.02,"end":32.94,"text":"Un golfe profond, refermé sur lui-même."},{"at":33.24,"end":38.88,"text":"Au fond, une butte de porphyre rose ; derrière elle, presque aussitôt, la montagne."},{"at":39.33,"end":42.76,"text":"Le nom dit l’âge du lieu : Portivechju, le port vieux."},{"at":43.06,"end":48.04,"text":"Des Grecs de Syracuse l’auraient fondé, ou repris, six siècles avant notre ère."}],"cues":{},"pins":{}},{"id":"port-vieux","from":48.74,"arrive":54.74,"voice":50.14,"leave":66.96,"lines":[{"at":50.14,"end":57.11,"text":"Un port, mais pas de ville. La plaine est fertile et presque déserte : les marais y donnent la fièvre."},{"at":57.56,"end":61.15,"text":"Seuls y descendent, l’hiver, les bergers de la montagne."},{"at":61.6,"end":66.26,"text":"Descendre l’hiver, remonter l’été : c’est le premier va-et-vient de cette histoire."}],"cues":{},"pins":{}},{"id":"citadelle","from":66.96,"arrive":93.07,"voice":69.96,"leave":94.07,"lines":[{"at":69.96,"end":78.26,"text":"En 1539, Gênes fonde ici une colonie, pour fermer ce refuge aux corsaires. Ses envoyés choisissent la hauteur."},{"at":78.71,"end":84.82,"text":"Les murs montent de 1541 à 1544. Cinq bastions."},{"at":86.02,"end":89.43,"text":"Derrière eux, un village, que Gênes peuple elle-même."}],"cues":{},"pins":{"bastion":78.71}},{"id":"ventimiglia","from":94.07,"arrive":100.07,"voice":95.47,"leave":112.98,"lines":[{"at":95.47,"end":103.47,"text":"La ville, elle, ne tient pas. Sampiero Corso la prend en 1564 ; elle est rasée l’année suivante."},{"at":103.92,"end":109.98,"text":"Des familles de Vintimille la relèvent, puis repartent. Les murs, eux, sont restés."},{"at":110.43,"end":112.28,"text":"Il ne manquait que des gens pour rester."}],"cues":{},"pins":{}},{"id":"ceux-d-en-haut","from":112.98,"arrive":120.98,"voice":115.78,"leave":131.15,"lines":[{"at":115.78,"end":122.95,"text":"Alors Gênes se tourne vers la montagne. Des familles descendent s’installer dans la citadelle, de Quenza surtout."},{"at":123.4,"end":130.45,"text":"Les deux noms de cette lettre viennent aussi de là-haut : les Rocca Serra, de Serra-di-Scopamène ; les Abbatucci, de Zicavo."}],"cues":{},"pins":{}},{"id":"estive","from":131.15,"arrive":136.15,"voice":132.55,"leave":150.47,"lines":[{"at":132.55,"end":134.3,"text":"Mais ils ne restent pas toute l’année."},{"at":134.6,"end":141.41,"text":"Chaque été, quand revient la fièvre, la ville se vide : on remonte à Quenza, à Zonza, à Levie, à l’Ospédale."},{"at":141.86,"end":145.58,"text":"On redescend à l’automne. Cela dure des générations."},{"at":146.03,"end":149.27,"text":"Ici, partir n’a jamais été le contraire d’appartenir."}],"cues":{},"pins":{}},{"id":"paoli","from":150.47,"arrive":158.47,"voice":153.27,"leave":175.57,"lines":[{"at":153.27,"end":159.32,"text":"Une carte vient de s’imprimer sur le plâtre : le Plan Terrier, premier relevé précis de ce rivage."},{"at":159.62,"end":161.49,"text":"Il commence l’année d’un départ."},{"at":161.94,"end":170.19,"text":"Le 13 juin 1769, vaincu à Ponte Novu, Pasquale Paoli embarque ici sur un navire anglais, pour l’exil."},{"at":170.64,"end":172.57,"text":"Quelque trois cents fidèles le suivent."}],"cues":{"sail":161.94},"pins":{}},{"id":"abbatucci","from":175.57,"arrive":181.57,"voice":176.97,"leave":199.41,"lines":[{"at":176.97,"end":181.21,"text":"L’homme qui a couvert sa retraite vient de Zicavo : Jacques Pierre Abbatucci."},{"at":181.66,"end":185.9,"text":"Selon la tradition familiale, c’est lui qui l’escorte jusqu’à ce port."},{"at":186.35,"end":189.24,"text":"Paoli reviendra, vingt et un ans plus tard."},{"at":189.54,"end":197.91,"text":"Jean-Charles, le fils du vieux général, ne reviendra pas : général à son tour, il est tué à vingt-six ans en défendant Huningue."}],"cues":{},"pins":{"jp":176.97,"jc":189.54}},{"id":"sel","from":199.41,"arrive":206.41,"voice":202.21,"leave":214.31,"lines":[{"at":202.21,"end":207.59,"text":"Au pied de la ville, là où le Stabiacciu rejoint le golfe, la carte dessine des marais."},{"at":208.04,"end":213.61,"text":"En 1795, l’autorisation d’y faire du sel est accordée à la famille Rocca Serra."}],"cues":{},"pins":{}},{"id":"sauniers","from":214.31,"arrive":220.31,"voice":215.71,"leave":229.16,"lines":[{"at":215.71,"end":221.78,"text":"On y travaillera deux siècles, jusqu’en l’an 2000. Ce seront les dernières salines de Corse."},{"at":222.23,"end":227.96,"text":"C’est aussi le moment où le nom entre à la mairie : en 1803, un Rocca Serra devient maire."}],"cues":{},"pins":{"plan":215.71}},{"id":"liege","from":229.16,"arrive":236.16,"voice":231.96,"leave":247.52,"lines":[{"at":231.96,"end":238.32,"text":"La carte s’efface. Voici la première photographie prise du ciel, en 1951."},{"at":238.77,"end":246.82,"text":"Sur la Marine travaille alors une usine de liège, fondée en 1876 : bouchons, flotteurs de filets, isolants."}],"cues":{},"pins":{}},{"id":"ecorce","from":247.52,"arrive":251.52,"voice":248.92,"leave":256.8,"lines":[{"at":248.92,"end":255.6,"text":"Le chêne-liège a ceci de rare qu’on peut le dépouiller sans le tuer. Dix à douze ans plus tard, l’écorce est revenue."}],"cues":{},"pins":{}},{"id":"train","from":256.8,"arrive":266.8,"voice":260.8,"leave":275.5,"lines":[{"at":260.8,"end":266.87,"text":"En 1935, le train atteint enfin Porto-Vecchio : Bastia est à cinq heures de voyage."},{"at":268.27,"end":274.3,"text":"En 1943, les bombardements l’interrompent. La ligne ne sera jamais rouverte."}],"cues":{"train":260.8},"pins":{}},{"id":"fievre","from":275.5,"arrive":283.5,"voice":278.3,"leave":293.66,"lines":[{"at":278.3,"end":282.7,"text":"Regardez l’anse en 1951 : encore ouverte, presque nue."},{"at":283,"end":286.75,"text":"Ce qui vidait cette plaine depuis des siècles vient à peine de céder."},{"at":287.2,"end":292.96,"text":"Le maire est alors un médecin, Camille de Rocca Serra : député, il soutient cette lutte à la Chambre."}],"cues":{},"pins":{}},{"id":"rivage-1975","from":293.66,"arrive":299.66,"voice":295.06,"leave":316.51,"lines":[{"at":295.06,"end":300.19,"text":"Au printemps 1949, la campagne contre les moustiques commence par Porto-Vecchio."},{"at":300.49,"end":306.81,"text":"De 1947 à 1949, les analyses positives y tombent d’environ deux cents à quatre."},{"at":307.26,"end":315.81,"text":"En 1950, un autre médecin devient maire : Jean-Paul de Rocca Serra, fils de Camille. Il le restera quarante-sept ans."}],"cues":{},"pins":{"analyses":300.49}},{"id":"rivage-2024","from":316.51,"arrive":322.51,"voice":317.91,"leave":332.42,"lines":[{"at":317.91,"end":322.61,"text":"La marina, les quais. Trois photographies, une seule anse."},{"at":323.06,"end":327.07,"text":"La fièvre n’a pas cédé devant un homme, mais devant une campagne d’État."},{"at":327.52,"end":331.72,"text":"Elle laisse une chose que la ville n’avait jamais eue : on peut désormais y passer l’été."}],"cues":{},"pins":{}},{"id":"ete","from":332.42,"arrive":339.42,"voice":335.22,"leave":349.19,"lines":[{"at":335.22,"end":342.46,"text":"Alors la saison change de sens. Pendant trois siècles, l’été vidait la ville ; désormais, il la remplit."},{"at":342.91,"end":347.69,"text":"Trois mille trois cents habitants en 1946. Plus de onze mille aujourd’hui."}],"cues":{},"pins":{"habitants":342.91}},{"id":"plages","from":349.19,"arrive":354.19,"voice":350.59,"leave":357.7,"lines":[{"at":350.59,"end":354.3,"text":"Ceux qui arrivent chaque été refont, sans le savoir, un très vieux chemin."},{"at":354.75,"end":356.2,"text":"Vous, vous le savez."}],"cues":{},"pins":{}},{"id":"soir","from":357.7,"arrive":365.7,"voice":360.5,"leave":381.58,"lines":[{"at":360.5,"end":367.76,"text":"Le dernier soir de juillet, on promène dans la vieille ville un mannequin de paille et de liège : Luddareddu, « petit juillet »."},{"at":368.21,"end":372.33,"text":"On le juge, on le pend, et à minuit on le brûle sur la place de l’église."},{"at":372.78,"end":377.2,"text":"Juillet était le mois du liège et du sel, celui où les hommes restaient en plaine."},{"at":377.5,"end":380.88,"text":"Le brûler, c’était fêter le jour où l’on pouvait enfin partir."}],"cues":{},"pins":{}},{"id":"deux-rues","from":381.58,"arrive":389.58,"voice":384.38,"leave":411.65,"lines":[{"at":384.38,"end":392.18,"text":"Descendez encore. Dans la vieille ville, le long des murs génois, une rue porte le nom du docteur Camille de Rocca Serra."},{"at":392.63,"end":398.09,"text":"Au bout, elle ne s’arrête pas : elle change seulement de nom, et devient la rue du Général-Abbatucci."},{"at":398.54,"end":404.59,"text":"Le docteur de la première rue est né à Zicavo, le village de la seconde, et sa mère était une Abbatucci."},{"at":405.04,"end":410.15,"text":"Les deux noms sont une seule famille. La montagne et la mer s’étaient épousées."}],"cues":{},"pins":{}},{"id":"rue","from":411.65,"arrive":422.65,"voice":416.65,"leave":432.45,"lines":[{"at":416.65,"end":418.63,"text":"La voici, à hauteur d’homme."},{"at":418.93,"end":424.05,"text":"La maquette s’arrête sur le seuil : ce qui se passe derrière les volets n’appartient pas aux cartes."},{"at":424.5,"end":428.44,"text":"Certains sont déjà revenus : dans la rue, des volets se sont rouverts."},{"at":428.89,"end":430.95,"text":"A casa piglia, a casa rende.","sub":"La maison rend toujours ce qu’elle prend.","kind":"proverb"}],"cues":{},"pins":{}},{"id":"envoi","from":432.45,"arrive":442.45,"voice":437.95,"leave":458.65,"lines":[{"at":437.95,"end":439.64,"text":"La nuit est tombée sur la maquette."},{"at":440.09,"end":447.19,"text":"Ici, tout le monde est parti, chaque année, et tout le monde est revenu : les bergers, les montagnards, Paoli lui-même."},{"at":447.64,"end":453.18,"text":"Si vous écoutez ceci de loin, vous n’êtes pas un visiteur. Vous êtes le prochain retour."},{"at":453.63,"end":456.65,"text":"Vous ne reconnaîtrez rien, et tout vous reconnaîtra."}],"cues":{},"pins":{}},{"id":"dedicace","from":458.65,"arrive":466.65,"voice":463.15,"leave":474.75,"lines":[{"at":463.15,"end":467.45,"text":"Aux Rocca Serra et aux Abbatucci, et à tous ceux qui en descendent.","quiet":true},{"at":468.45,"end":469.75,"text":"Pace è salute.","quiet":true}],"cues":{},"pins":{}}]};
